#include <windows.h>
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
int main(int argc,char**argv){if(argc<4){printf("usage: importdump <exe> <input> <dump>\n");return 2;}SECURITY_ATTRIBUTES sa={sizeof(sa),NULL,TRUE};HANDLE hin=CreateFileA(argv[2],GENERIC_READ,FILE_SHARE_READ,&sa,OPEN_EXISTING,FILE_ATTRIBUTE_NORMAL,NULL);STARTUPINFOA si;PROCESS_INFORMATION pi;ZeroMemory(&si,sizeof(si));ZeroMemory(&pi,sizeof(pi));si.cb=sizeof(si);si.dwFlags=STARTF_USESTDHANDLES;si.hStdInput=hin;si.hStdOutput=GetStdHandle(STD_OUTPUT_HANDLE);si.hStdError=GetStdHandle(STD_ERROR_HANDLE);char cmd[4096];snprintf(cmd,sizeof(cmd),"/"%s/"",argv[1]);printf("COMMAND: CreateProcessA %s DEBUG_ONLY_THIS_PROCESS\n",argv[1]);if(!CreateProcessA(argv[1],cmd,NULL,NULL,TRUE,DEBUG_ONLY_THIS_PROCESS|CREATE_NO_WINDOW,NULL,NULL,&si,&pi)){printf("CreateProcess error=%lu\n",GetLastError());return 4;}CloseHandle(hin);ULONG_PTR base=0;int dumped=0,done=0,n=0;while(!done&&n++<10000){DEBUG_EVENT e;if(!WaitForDebugEvent(&e,5000)){printf("WaitForDebugEvent error=%lu\n",GetLastError());break;}DWORD c=DBG_CONTINUE;if(e.dwDebugEventCode==CREATE_PROCESS_DEBUG_EVENT){base=(ULONG_PTR)e.u.CreateProcessInfo.lpBaseOfImage;printf("CREATE_PROCESS base=%p start=%p\n",(void*)base,e.u.CreateProcessInfo.lpStartAddress);if(e.u.CreateProcessInfo.hFile)CloseHandle(e.u.CreateProcessInfo.hFile);}else if(e.dwDebugEventCode==LOAD_DLL_DEBUG_EVENT){if(e.u.LoadDll.hFile)CloseHandle(e.u.LoadDll.hFile);}else if(e.dwDebugEventCode==EXCEPTION_DEBUG_EVENT){DWORD code=e.u.Exception.ExceptionRecord.ExceptionCode;printf("EXCEPTION code=0x%08lx addr=%p chance=%lu\n",code,e.u.Exception.ExceptionRecord.ExceptionAddress,e.u.Exception.dwFirstChance);if(code==EXCEPTION_BREAKPOINT||code==EXCEPTION_SINGLE_STEP)c=DBG_CONTINUE;else{if(!dumped&&code==0xc0000005){dumped=1;DWORD size=0x3000;unsigned char*b=(unsigned char*)malloc(size);SIZE_T got=0;if(ReadProcessMemory(pi.hProcess,(LPCVOID)(base+0xc000),b,size,&got)){HANDLE h=CreateFileA(argv[3],GENERIC_WRITE,0,NULL,CREATE_ALWAYS,FILE_ATTRIBUTE_NORMAL,NULL);DWORD wr=0;BOOL ok=h!=INVALID_HANDLE_VALUE&&WriteFile(h,b,(DWORD)got,&wr,NULL);if(h!=INVALID_HANDLE_VALUE)CloseHandle(h);printf("DUMP rva=0xc000 path=%s requested=%lu read=%llu written=%lu ok=%u\n",argv[3],size,(unsigned long long)got,wr,ok);}else printf("ReadProcessMemory error=%lu read=%llu\n",GetLastError(),(unsigned long long)got);free(b);}c=DBG_EXCEPTION_NOT_HANDLED;}}else if(e.dwDebugEventCode==EXIT_PROCESS_DEBUG_EVENT){printf("EXIT_PROCESS code=0x%08lx\n",e.u.ExitProcess.dwExitCode);done=1;}if(!ContinueDebugEvent(e.dwProcessId,e.dwThreadId,c)){printf("ContinueDebugEvent error=%lu\n",GetLastError());break;}}DWORD ec=0;GetExitCodeProcess(pi.hProcess,&ec);printf("debug_exit=%lu events=%d dumped=%d\n",ec,n,dumped);CloseHandle(pi.hThread);CloseHandle(pi.hProcess);return 0;}
